const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const splitData = $('Split Out').all()[i]?.json || {};
  let rawHtml = items[i].json.data || items[i].json.raw_content || "";
  let extractedText = "";

  // 1. Clean snippet string
  let rawSnippet = splitData.snippet || "";
  let cleanSnippet = rawSnippet
    .replace(/\[SUMMARY SNIPPET\]/gi, "")
    .replace(/\\n/g, " ")
    .replace(/\r?\n|\r/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  // 2. Try JSON-LD Extraction if raw HTML was passed
  const jsonLdMatch = rawHtml.match(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/i);

  if (jsonLdMatch && jsonLdMatch[1]) {
    try {
      const parsed = JSON.parse(jsonLdMatch[1]);
      if (parsed['@type'] === 'JobPosting' && parsed.description) {
        extractedText = parsed.description.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
      }
    } catch (e) {
      extractedText = "";
    }
  }

  // 3. Handle Jina Markdown Output or Fallback
  if (!extractedText) {
    // If rawHtml has markdown text (from Jina Reader), use it!
    if (rawHtml.length > 200) {
      // Strip Jina headers/footers if present, keeping full body
      extractedText = rawHtml
        .replace(/\\n/g, "\n")
        .replace(/\n{3,}/g, "\n\n")
        .trim();
    } else {
      extractedText = `[NOTE: This URL is a company job board index page, not an individual job post.]\nSnippet Summary: ${cleanSnippet}`;
    }
  } else if (cleanSnippet) {
    extractedText = `Snippet: ${cleanSnippet}\n\n${extractedText}`;
  }

  // Output all necessary fields cleanly
  items[i].json = {
    id: splitData.id || items[i].json.id,
    title: splitData.title || items[i].json.title,
    link: splitData.link || items[i].json.link,
    sanitizedContent: extractedText
  };
}

return items;

const results = [];
const allInputs = $input.all();
const splitOutItems = $('Split Out').all();
const codeSanitizerItems = $('Code Sanitizer').all();

// Filter valid records from the SQL query node that have actual IDs
const sqlItems = $('PostgreSQL/Supabase -dedublicate & Checking').all().filter(item => item.json && item.json.id !== undefined);

for (let i = 0; i < allInputs.length; i++) {
  const item = allInputs[i];
  try {
    let rawData = item.json;

    // Index-matched fallback objects
    const splitItem = splitOutItems[i]?.json || {};
    const sanitizerItem = codeSanitizerItems[i]?.json || {};
    const sqlItem = sqlItems[i]?.json || {};

    // Retrieve id, created_at, link, title, and date dynamically
    const originalId = item.json.id || sqlItem.id || splitItem.id || null;
    const originalCreatedAt = item.json.created_at || sqlItem.created_at || splitItem.created_at || null;
    const originalLink = item.json.link || item.json.url || sqlItem.link || splitItem.link || null;
    const originalTitle = item.json.title || sqlItem.title || splitItem.title || null;
    const originalDate = item.json.date || splitItem.date || null;
    const originalRawContent = item.json.raw_content || sanitizerItem.sanitizedContent || splitItem.raw_content || null;

    // Unwrap nested 'output' property if present from Gemini/LLM node
    if (rawData.output) {
      rawData = rawData.output;
    }

    // Safely parse raw string if the LLM outputted stringified JSON
    let data = rawData;
    if (typeof rawData === 'string') {
      const cleanedString = rawData
        .replace(/```json/g, '')
        .replace(/```/g, '')
        .trim();
      data = JSON.parse(cleanedString);
    }

    // Strict Schema Validation
    const requiredKeys = [
      'company',
      'remote_type',
      'location_constraint',
      'tech_stack',
      'market_demand_signals',
      'operational_bottleneck',
      'role_compatibility_score',
      'hirability_score',
      'hiring_urgency',
      'compatibility_verdict',
      'roi_pitch'
    ];

    for (const key of requiredKeys) {
      if (data[key] === undefined || data[key] === null || data[key] === '') {
        throw new Error(`Missing or empty required schema key: '${key}'`);
      }
    }

    // Validate array integrity
    if (!Array.isArray(data.tech_stack) || data.tech_stack.length === 0) {
      throw new Error("'tech_stack' must be a non-empty array");
    }
    if (!Array.isArray(data.market_demand_signals) || data.market_demand_signals.length === 0) {
      throw new Error("'market_demand_signals' must be a non-empty array");
    }

    // Output all fields explicitly
    results.push({
      json: {
        id: originalId,
        created_at: originalCreatedAt,
        link: originalLink,
        title: originalTitle,
        company: data.company,
        status: data.status || '📝 Drafted',
        tech_stack: data.tech_stack,
        roi_pitch: data.roi_pitch,
        raw_content: originalRawContent,
        operational_bottleneck: data.operational_bottleneck,
        remote_type: data.remote_type,
        location_constraint: data.location_constraint,
        market_demand_signals: data.market_demand_signals,
        hirability_score: data.hirability_score,
        hiring_urgency: data.hiring_urgency,
        compatibility_verdict: data.compatibility_verdict,
        role_compatibility_score: data.role_compatibility_score,
        date: originalDate
      }
    });

  } catch (error) {
    results.push({
      json: {
        error: error.message,
        raw: item.json
      }
    });
  }
}

return results;

